1.3 Going for it on 4th Down


Code
fourth.all &lt;-pbp |&gt;  
    filter(down == 4,
    game_seconds_remaining &gt; 1799,
    goal_to_go==0,
    fourth_down_failed ==1 | fourth_down_converted == 1
    ) |&gt; 

  group_by(to_go_f) |&gt;  
  summarise(pass_percent = mean(pass_attempt, na.rm = TRUE),
            Attempts=n())|&gt; 
  mutate(Team = "NFL")




Code
# New England
fourth.pats &lt;-pbp |&gt;  
    filter(down == 4,
    posteam == "NE", # pats only
    game_seconds_remaining &gt; 1799,
    goal_to_go==0,
    fourth_down_failed ==1 | fourth_down_converted == 1
    ) |&gt; 

  group_by(to_go_f) |&gt;  
  summarise(pass_percent = mean(pass_attempt, na.rm = TRUE),
            Attempts=n()) |&gt; 
  mutate(Team = "Patriots")




Code
# Los Angeles 
fourth.rams &lt;-pbp |&gt;  
    filter(down == 4,
    posteam == "LA", # rams only
    game_seconds_remaining &gt; 1799,
    goal_to_go==0,
    fourth_down_failed ==1 | fourth_down_converted == 1
    ) |&gt; 

  group_by(to_go_f) |&gt;  
  summarise(pass_percent = mean(pass_attempt, na.rm = TRUE),
            Attempts=n()) |&gt; 
  mutate(Team = "Rams")




Code
fourth.combined &lt;- bind_rows(fourth.all, fourth.pats, fourth.rams) |&gt; 
  select(Team, everything()) 

fourth.combined |&gt; 
  flextable() |&gt; 
  set_header_labels(
    to_go_f = "Yards to Go",
    pass_percent = "Pass Rate"
  ) |&gt;
  bg(i = ~ Team == "NFL", bg = "antiquewhite") |&gt;
  bg(i = ~ Team == "Patriots", bg = "lightblue") |&gt;
  bg(i = ~ Team == "Rams", bg = "#FFD100") |&gt;
  bold(j = "Team") |&gt;
  merge_v(j = "Team") |&gt;
  valign(valign = "top", j = "Team") |&gt;
  autofit()


